export function used() {
  return 'ns-used';
}

export function unusedNs() {
  // Deliberately large body so stubbing is measurable in bytes removed.
  const table = [];
  for (let i = 0; i < 64; i++) {
    table.push({ index: i, square: i * i, cube: i * i * i, label: `row-${i}` });
  }
  const summary = table.reduce(
    (acc, row) => {
      acc.squares += row.square;
      acc.cubes += row.cube;
      acc.labels.push(row.label.toUpperCase());
      return acc;
    },
    { squares: 0, cubes: 0, labels: [] },
  );
  const digest = summary.labels.filter((l) => l.endsWith('3')).join('|');
  return `${summary.squares}:${summary.cubes}:${digest}`;
}
